INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(49474, 'koKR', '저주받은 파편', '저주받은 파편을 부서진 섬의 달라란에 있는 비전역술사 브리디엘에게 가져가야 합니다.', '<여러 가지 빛깔로 부자연스럽게 변하는 금속 파편이 당신의 눈길을 끕니다. 파편을 건드리자 한쪽 모서리가 부풀어 오르더니 이내 녹아버립니다. 액체 방울이 땅에 떨어지자 쉬이익 하는 소리와 함께 고약한 악취가 코를 찌릅니다.$b$b달라란에서 금속을 다루는 누군가가 당신에게 무언가를 얘기해줄 수 있을지도 모릅니다.>', '', '', '', '', '', '', 25549),
(49473, 'koKR', '중대한 노력', '각성의 정수 $1oa개를 비전역술사 브리디엘에게 가져가야 합니다.', '날이 갈수록 물질의 반응이 점점 강해집니다. 군단과의 싸움에서 승리할지라도, 우리에게 굉장히 소중한 것을 잃을 수도 있습니다. \n\n이게 앞으로 다가올 더욱 큰 격변의 징조일까요? 우리 세계 앞에 어떤 운명이 기다리는 걸까요, $n 님?\n\n저는 가열로 앞에서 답을 찾아내겠습니다, 제 일생 동안 그랬듯이요. 당신이 찾을 답은 다른 어딘가에 있을 것 같습니다.', '', '', '', '', '', '', 25549),
(49472, 'koKR', '중대한 노력', '각성의 정수 $1oa개를 비전역술사 브리디엘에게 가져가야 합니다.', '일리단이 운명의 손을 이끌었을지는 모르지만, 아르거스를 아제로스 가까이로 불러오는 바람에 밤샘이 붕괴되며 나타났던 현상들이 더욱 가속되고 있습니다.\n\n군단이 아르거스에서 벌이는 짓이 우리가 몇 년이나 무의식적으로 사용해 온 힘을 더욱 건드리는 게 분명합니다.\n\n두말할 필요 없이 이 일을 더 깊게 연구해야겠죠.', '', '', '', '', '', '', 25549),
(49445, 'koKR', '원초적 거래', '', '', '', '', '', '', '', '', 25549),
(49293, 'koKR', '침공 공습', '일반 침공 거점 3개를 완료해야 합니다.', '군단에게 단 하나의 세계도 양보해선 안 된다. 침공 거점을 끊임없이 공격해서 군단을 발아래에 무릎 꿇려라.', '', '', '', '', '', '', 25549),
(49224, 'koKR', '황천빛 도가니', '황천빛 도가니를 이용해 황천빛 강화로 성물에 마력을 주입해야 합니다.', '도가니가 힘으로 들끓고 있습니다. 곧 우리의 무기도 마치 별처럼 빛날 겁니다!\n\n그 힘이 있어야만, 이곳에서 군단을 무찌를 실낱같은 희망이 보일 것입니다.\n\n$n 님, 당신이 엄청난 어려움을 견뎌낸 덕에 우리는 이 순간까지 올 수 있었습니다. 도가니의 힘을 처음 이용하는 영예는 당신이 가져가셔야 합니다.', '', '', '', '', '', '', 25549),
(49196, 'koKR', '상급 침공 거점: 지옥의 군주 바일머스', '', '', '', '', '', '', '', '', 25549),
(49195, 'koKR', '상급 침공 거점: 오큘라러스', '', '', '', '', '', '', '', '', 25549),
(49143, 'koKR', '빛의 어머니의 정수', '빛의 흔적 $1oa개를 모아야 합니다.', '중대한 순간이네, $n. 우리 대장정의 기세가 꺾여선 안 되네.\n\n제라는 쓰러졌지만, 여전히 그녀의 존재가 우리 주위에서 느껴지네. 그 심장 안에서 반짝이던 빛이 우리 대의를 실현해 줄 힘의 원천이 될 수 있을 걸세.\n\n제라를 잃은 것이 투랄리온에게는 틀림없이 깊은 상처가 되었겠지. 자네가 남아있는 나루의 흔적을 모아오는 동안 나는 투랄리온이 불안함을 덜 수 있도록 할 수 있는 일을 하겠네.', '', '', '', '', '', '', 25549),
(49135, 'koKR', '아르거스의 심장', '안토러스 - 불타는 왕좌 신화 난이도에서 아그라마르를 처치하고 암흑 티탄의 인장 4개를 모아야 합니다.', '하투운이 얘기하길 아르거스가 군단의 손에 넘어갔을 때 살게라스가 행성 중심부 깊은 곳에 암흑의 사원을 지으라고 명했다더군요. 이 사원에 대해 알려진 것은 거의 없습니다. 그에게 가장 충성하는 하수인에게만 사원에 들어갈 수 있는 인장이 주어진다는 것 말고는요.\n\n인장을 차지하고 나면 그걸 구원호에 주입할 수 있을 겁니다. 그러면 우리 병력이 썩어 문드러진 아르거스 심장부로 직접 쳐들어갈 수 있게 될 겁니다.', '', '', '', '', '', '', 25549),
(49134, 'koKR', '아르거스의 심장', '안토러스 - 불타는 왕좌 영웅 난이도에서 아그라마르를 처치하고 암흑 티탄의 인장 4개를 모아야 합니다.', '하투운이 얘기하길 아르거스가 군단의 손에 넘어갔을 때 살게라스가 행성 중심부 깊은 곳에 암흑의 사원을 지으라고 명했다더군요. 이 사원에 대해 알려진 것은 거의 없습니다. 그에게 가장 충성하는 하수인에게만 사원에 들어갈 수 있는 인장이 주어진다는 것 말고는요.\n\n인장을 차지하고 나면 그걸 구원호에 주입할 수 있을 겁니다. 그러면 우리 병력이 썩어 문드러진 아르거스 심장부로 직접 쳐들어갈 수 있게 될 겁니다.', '', '', '', '', '', '', 25549),
(49133, 'koKR', '아르거스의 심장', '안토러스 - 불타는 왕좌 일반 난이도에서 아그라마르를 처치하고 암흑 티탄의 인장 4개를 모아야 합니다.', '하투운이 얘기하길 아르거스가 군단의 손에 넘어갔을 때 살게라스가 행성 중심부 깊은 곳에 암흑의 사원을 지으라고 명했다더군요. 이 사원에 대해 알려진 것은 거의 없습니다. 그에게 가장 충성하는 하수인에게만 사원에 들어갈 수 있는 인장이 주어진다는 것 말고는요.\n\n인장을 차지하고 나면 그걸 구원호에 주입할 수 있을 겁니다. 그러면 우리 병력이 썩어 문드러진 아르거스 심장부로 직접 쳐들어갈 수 있게 될 겁니다.', '', '', '', '', '', '', 25549),
(49099, 'koKR', '침공 거점: 보니크', '', '', '', '', '', '', '', '', 25549),
(49098, 'koKR', '침공 거점: 센가르', '', '', '', '', '', '', '', '', 25549),
(49097, 'koKR', '침공 거점: 센구아', '', '', '', '', '', '', '', '', 25549),
(49096, 'koKR', '침공 거점: 나익탈', '', '', '', '', '', '', '', '', 25549),
(49091, 'koKR', '침공 거점: 밸', '', '', '', '', '', '', '', '', 25549),
(49077, 'koKR', '숙고의 시간', '일리단의 수정을 그와 가까운 사람들과 장소로 가져가야 합니다.', '<마법의 힘을 내뿜는 수정이 당신을 부릅니다.\n\n수정을 움켜쥐자 일리단이 당신을 믿고 남겨 놓은 전언이 들려옵니다.>', '', '', '', '', '', '', 25549),
(49076, 'koKR', '어둠의 통로', '안토러스 - 불타는 왕좌 신화 난이도에서 영혼사냥꾼 이모나르를 처치하고 통로의 룬 4개를 모아야 합니다.', '아르거스 심장부에 위험한 마력이 넘치고 있는데도 영혼사냥꾼은 불타는 왕좌를 제멋대로 돌아다닙니다. 저희 정찰병이 보고하기를, 놈의 함선은 악마의 룬에서 나오는 힘을 이용해 신성한 지옥작업장에 안전하게 접근한다더군요.\n\n그 룬을 손에 넣으면 구원호도 같은 항로를 따라갈 수 있을 겁니다. 귀중한 시간도 절약할 수 있을 거고요.', '', '', '', '', '', '', 25549),
(49075, 'koKR', '어둠의 통로', '안토러스 - 불타는 왕좌 영웅 난이도에서 영혼사냥꾼 이모나르를 처치하고 통로의 룬 4개를 모아야 합니다.', '아르거스 심장부에 위험한 마력이 넘치고 있는데도 영혼사냥꾼은 불타는 왕좌를 제멋대로 돌아다닙니다. 저희 정찰병이 보고하기를, 놈의 함선은 악마의 룬에서 나오는 힘을 이용해 신성한 지옥작업장에 안전하게 접근한다더군요.\n\n그 룬을 손에 넣으면 구원호도 같은 항로를 따라갈 수 있을 겁니다. 귀중한 시간도 절약할 수 있을 거고요.', '', '', '', '', '', '', 25549),
(49057, 'koKR', '꼬마락시스', '', '', '', '', '', '', '', '', 25549),
(49048, 'koKR', '킁킁마르술', '', '', '', '', '', '', '', '', 25549),
(49042, 'koKR', '썩은발톱이', '', '', '', '', '', '', '', '', 25549),
(49032, 'koKR', '어둠의 통로', '안토러스 - 불타는 왕좌 일반 난이도에서 영혼사냥꾼 이모나르를 처치하고 통로의 룬 4개를 모아야 합니다.', '아르거스 심장부에 위험한 마력이 넘치고 있는데도 영혼사냥꾼은 불타는 왕좌를 제멋대로 돌아다닙니다. 저희 정찰병이 보고하기를, 놈의 함선은 악마의 룬에서 나오는 힘을 이용해 신성한 지옥작업장에 안전하게 접근한다더군요.\n\n그 룬을 손에 넣으면 구원호도 같은 항로를 따라갈 수 있을 겁니다. 귀중한 시간도 절약할 수 있을 거고요.', '', '', '', '', '', '', 25549),
(49015, 'koKR', '티탄의 죽음', '안토러스 - 불타는 왕좌에서 아르거스의 영혼을 쓰러뜨려야 합니다.', '나의 이 깊은 슬픔을, 이 분노를 표현할 길이 없네. 살게라스는 대체 무슨 짓을 저지른 것인가...$b$b내 고향 아르거스가 티탄의 영혼을 품고 있네. 구제할 수 없을 정도로 뒤틀리고 타락한 그 영혼이, 군단의 무한한 군대를 강화하기 위해 이용되고 있네.$b$b우린 불가능에 도전해야 하네... 안토러스의 벽을 뚫고 들어가 군단과 세계영혼과의 연결을 끊어야 하네.$b$b부디 이 고통과 괴로움을 끝내주게, $n. 아르거스의 어두운 심장부를 치면 우리는 군단을 무찌르고... 내 고향의 영혼을 구원할 수 있을 걸세.', '', '', '', '', '', '', 25549),
(49014, 'koKR', '불타는 왕좌', '안토란 황무지의 상공에서 대기술병 로뮬과 대화하여 안토러스로 가는 길을 열어야 합니다.', '때가 왔습니다, $n 님. 안토러스에 공격을 가할 시간입니다. 우리가 지키려 했던 모든 것들, 우리의 동료와 가족들이 희생했던 모든 것들이 저희를 이 순간으로 이끌었습니다.$b$b이제 빛의 심판을 저 저주받은 성채의 문에 발사하고 놈들의 권좌를 휩쓸 것입니다. 군단을 끝장낼 겁니다.$b$b당신께서 한 일이니, 이 영예는 당신이 가져가는 게 마땅합니다. 로뮬에게 말을 걸어 함께 이 임무를 마무리 지으시지요.', '', '', '', '', '', '', 25549),
(49007, 'koKR', '사령관이 기다린다!', '비샥스의 차원문을 사용해야 합니다.', '<장치에 동력이 들어오더니 안토란 황무지에 있는 편대 사령관 비샥스의 차원문을 가동시킵니다.>', '', '', '', '', '', '', 25549),
(48983, 'koKR', '채광 단속', '', '', '', '', '', '', '', '', 25549),
(48982, 'koKR', '침공 거점: 아우리노르', '', '', '', '', '', '', '', '', 25549),
(48977, 'koKR', '빛의 군대의 물자', '구원호에 있는 구원자 잴라아나와 대화해서 보상을 받아야 합니다.', '아르케논 포로스, 영웅이여.\n\n빛의 군대는 아르거스에 있는 군단 병력에 대항해 주신 당신의 노고에 감사를 드리고 싶습니다.\n\n감사의 표시로 이 보관함을 드리니 부디 받아주십시오. 당신의 끊임없는 지원 덕분에 군단을 영원히 몰아내려는 저희의 궁극적인 목표에 어느 때보다 가까이 다가갔습니다.', '', '', '', '', '', '', 25549),
(48976, 'koKR', '아르거스 세력단의 물자', '구원호에 있는 존경받는 토라안과 대화해야 합니다.', '$ct|1이여;여;, 당신이 애써준 덕에 우리 병력이 자원을 확보해 군단의 손에 들어가는 것을 막을 수 있었습니다.\n\n당신이 계속 도와준다면 우리 군대가 더 많은 자원을 제공할 수 있을 것입니다.', '', '', '', '', '', '', 25549),
(48974, 'koKR', '빛의 군대와 불멸의 동맹', '구원호에 있는 구원자 잴라아나와 대화해야 합니다.', '빛의 군대 동맹군이 당신의 끊임없는 노고에 감사를 표하고 싶어합니다. 구원호에서 기다리고 있다고 합니다.', '', '', '', '', '', '', 25549),
(48973, 'koKR', '아르거스 세력단과 불멸의 동맹', '구원호에 있는 존경받는 토라안과 대화해야 합니다.', '아르거스 세력단 동맹군이 당신에게 방문해 줄 것을 요청했습니다. 지금껏 협력해 준 당신에게 보답을 하고 싶은 것 같습니다.', '', '', '', '', '', '', 25549),
(48958, 'koKR', '의식 방해', '', '', '', '', '', '', '', '', 25549),
(48954, 'koKR', '티탄의 피', '달라란에 있는 카드가에게 사멸자 아르거스의 피를 가져가야 합니다.', '<쓰러진 티탄 아르거스의 몸에서 흘러나온 피가 당신의 눈앞에서 엉겨붙어 티끌 하나 없는 보석으로 변합니다. 보석을 손에 쥐자 안에서 뿜어져 나오는 헤아릴 수 없는 힘... 그리고 고통과 슬픔의 메아리가 느껴집니다.\n\n이것은 이기리라 생각지 못했던 전쟁의 마지막 잔재입니다. 믿을 수 없는 업적입니다. 하지만 그간 일궈왔던 모든 승리와 마찬가지로 이 일에도 엄청난 대가가 따랐습니다.\n\n당신은 곧 이 전리품을 누구에게 가져가야 하는지 알아차립니다.>', '', '', '', '', '', '', 25549),
(48953, 'koKR', '삼두정의 권좌: 암흑소환사', '', '', '', '', '', '', '', '', 25549),
(48952, 'koKR', '청소란 이런 것', '', '', '', '', '', '', '', '', 25549),
(48951, 'koKR', '삼두정의 권좌: 공허아귀', '', '', '', '', '', '', '', '', 25549),
(48937, 'koKR', '황천방랑자의 차원문 생성기 생성', '', '', '', '', '', '', '', '', 25549),
(48931, 'koKR', '깨어난 거수', '', '', '', '', '', '', '', '', 25549),
(48929, 'koKR', '저항 세력 키우기', '투랄리온과 대화해야 합니다.', '안토러스를 공격할 자원이 부족하다는 걸 네 대총독이 알면 분명 초조해 하겠지. 본인의 자랑스러운 빛의 군대가 이런 무력한 상황에 처했다는 걸 인정하는 데 익숙하지 않은 자이니 말이야.\n\n그의 자부심은 내가 신경 쓸 바가 아니지. 그가 새로운 작전을 짤 동안 나는 이 땅을 악마의 피로 적실 것이다.\n\n가라. 마지막 승리를 쟁취하기 위해 끝내야 할 일이 굉장히 많다.', '', '', '', '', '', '', 25549),
(48912, 'koKR', '안토란 대장정 물자 공급', '침공 거점 10개를 완료해야 합니다.', '군단은 놈들이 정복한 세계에서 원자재를 얻어 군대를 강화하는 데 씁니다. 군단 차원문으로 들어가 마주치는 악마들을 처치하십시오. 놈들에게 전쟁 기계를 유지하는 데 쓸 자원을 허락지 마십시오.', '', '', '', '', '', '', 25549),
(48911, 'koKR', '공허 예방', '응축된 공허의 파편 100개를 모아야 합니다.', '그림자에 물든 존재가 죽으면 공허의 흔적을 남깁니다. 도시를 돌아다니면서 이걸 구해오면 제가 증류해 원액을 모으겠습니다.\n\n그러면 우리 형제들을 더 많이 구할 수 있을 겁니다.', '', '', '', '', '', '', 25549),
(48910, 'koKR', '크로쿠운 물자 조달', '$1oa의 연맹 전당 자원을 모아야 합니다.', '이 황량한 곳에서는 얻을 게 거의 없습니다. 모두가 매시간을 생존 물자를 긁어 모으는 데 쓰고 있습니다. 보급품을 조금 더 얻을 수 있다면 다른 마루추적자 한 명을 드릴 수 있을 텐데 말입니다.\n\n어떻게 생각하십니까, 이방인이여?', '', '', '', '', '', '', 25549),
(48875, 'koKR', '부패한 연금술', '', '', '', '', '', '', '', '', 25549),
(48867, 'koKR', '수석 연금술사 먼큘러스', '', '', '', '', '', '', '', '', 25549),
(48864, 'koKR', '뒤틀린 대장장이', '대장장이 가알을 찾아야 합니다.', '$C님, 이건 삼두정의 무기고 열쇠 조각인 것 같습니다. 무기고는 우리가 아르거스에서 퇴각할 때 잠가 두었습니다. 지난번에 제 부관 아탈라아가 병력을 이끌고 무기고를 탈환하려 했는데... 그것도 한참 전 일이군요.\n\n이 열쇠를 아는 이가 한 명 더 있습니다. 열쇠를 만든 대장장이 가알이죠. 크로쿠운에 뒤틀린 드레나이가 살고 있다니 가알도 아직 살아 있을지 모릅니다.', '', '', '', '', '', '', 25549),
