(27560, 'koKR', '아르거스의 일지', '', '', '', '', '', '', '', '', 25549),
(27559, 'koKR', '벡스툴의 완장', '', '', '', '', '', '', '', '', 25549),
(27558, 'koKR', '파멜라의 인형', '', '', '', '', '', '', '', '', 25549),
(27557, 'koKR', '타레나의 부적', '', '', '', '', '', '', '', '', 25549),
