(13016, 'koKR', '장로 노르탈', '', '', '', '', '', '', '', '', 25549),
(13015, 'koKR', '장로 파르갈', '', '', '', '', '', '', '', '', 25549),
(13014, 'koKR', '장로 모르시', '', '', '', '', '', '', '', '', 25549),
